public void compensate() {
  if (options.parallelCompensation) {
    List<Promise> results = new ArrayList<>();
    for (Functions.Func<Promise> f : compensationOps) {
      results.add(f.apply());
    }

    CompensationException sagaException = null;
    for (Promise p : results) {
      try {
        p.get();
      } catch (Exception e) {
        if (sagaException == null) {
          sagaException = new CompensationException(e);
        } else {
          sagaException.addSuppressed(e);
        }
      }
    }

    if (sagaException != null) {
      throw sagaException;
    }
  } else {
    for (int i = compensationOps.size() - 1; i >= 0; i--) {
      Functions.Func<Promise> f = compensationOps.get(i);
      try {
        Promise result = f.apply();
        result.get();
      } catch (Exception e) {
        if (!options.continueWithError) {
          throw e;
        }
      }
    }
  }

 * Add compensation operation for saga.
 *
 * @param operation to be executed during compensation.
 */
public void addCompensation(Functions.Proc operation) {
  compensationOps.add(() -> Async.procedure(operation));
}

export const createOrderWorkflow = createWorkflow(
  createOrdersWorkflowId,
  (input: WorkflowData<CreateOrderWorkflowInput>) => {
    const variantIds = transform({ input }, (data) => {
      return (data.input.items ?? [])
        .map((item) => item.variant_id)
        .filter(Boolean) as string[]
    })

    const [salesChannel, region, customerData] = parallelize(
      findSalesChannelStep({
        salesChannelId: input.sales_channel_id,
      }),
      findOneOrAnyRegionStep({
        regionId: input.region_id,
      }),
      findOrCreateCustomerStep({
        customerId: input.customer_id,
        email: input.email,
      })
    )

const orderToCreate = transform(
  { translatedLineItems, orderInput },
  (data) => {
    return {
      ...data.orderInput,
      items: data.translatedLineItems,
    }
  }
)

const orders = createOrdersStep([orderToCreate])
const order = transform({ orders }, (data) => data.orders?.[0])

export const createOrdersStep = createStep(
  createOrdersStepId,
  async (data: CreateOrderDTO[], { container }) => {
    const service = container.resolve<IOrderModuleService>(Modules.ORDER)

    const created = await service.createOrders(data)
    return new StepResponse(
      created,
      created.map((store) => store.id)
    )
  },
  async (createdIds, { container }) => {
    if (!createdIds?.length) {
      return
    }

    const service = container.resolve<IOrderModuleService>(Modules.ORDER)

    await service.deleteOrders(createdIds)
  }

    if (!customer) {
      customer = await service.createCustomers({ email: validatedEmail })
      customerWasCreated = true
    }

    originalCustomer = customer

    customerData.customer = customer
    customerData.email = customer.email
  }

  return new StepResponse(customerData, {
    customer: originalCustomer,
    customerWasCreated,
  })
},
