/*
 * Create the transient table that will receive the regenerated data. Lock
 * it against access by any other process until commit (by which time it
 * will be gone).
 */
OIDNewHeap = make_new_heap(matviewOid, tableSpace,
						   matviewRel->rd_rel->relam,
						   relpersistence, ExclusiveLock);
Assert(CheckRelationOidLockedByMe(OIDNewHeap, AccessExclusiveLock, false));

/* Generate the data, if wanted. */
if (!skipData)
{
	DestReceiver *dest;

	dest = CreateTransientRelDestReceiver(OIDNewHeap);
	processed = refresh_matview_datafill(dest, dataQuery, queryString,
										 is_create);

/* Make the matview match the newly generated data. */
if (concurrent)
{
	int			old_depth = matview_maintenance_depth;

	PG_TRY();
	{
		refresh_by_match_merge(matviewOid, OIDNewHeap, relowner,
							   save_sec_context);
	}
	PG_CATCH();
	{
		matview_maintenance_depth = old_depth;
		PG_RE_THROW();
	}
	PG_END_TRY();
	Assert(matview_maintenance_depth == old_depth);
}
else
{
	refresh_by_heap_swap(matviewOid, OIDNewHeap, relpersistence);

refresh_matview_datafill(DestReceiver *dest, Query *query,
						 const char *queryString, bool is_create)
{
	List	   *rewritten;
	PlannedStmt *plan;
	QueryDesc  *queryDesc;
	Query	   *copied_query;
	uint64		processed;

	/* Lock and rewrite, using a copy to preserve the original query. */
	copied_query = copyObject(query);
	AcquireRewriteLocks(copied_query, true, false);
	rewritten = QueryRewrite(copied_query);

	/* SELECT should never rewrite to more or less than one SELECT query */
	if (list_length(rewritten) != 1)
		elog(ERROR, "unexpected rewrite result for %s",
			 is_create ? "CREATE MATERIALIZED VIEW " : "REFRESH MATERIALIZED VIEW");
	query = (Query *) linitial(rewritten);

	/* Check for user-requested abort. */
	CHECK_FOR_INTERRUPTS();

	/* Plan the query which will generate data for the refresh. */
	plan = pg_plan_query(query, queryString, CURSOR_OPT_PARALLEL_OK, NULL, NULL);

	/*
	 * Use a snapshot with an updated command ID to ensure this query sees
	 * results of any previously executed queries.  (This could only matter if
	 * the planner executed an allegedly-stable function that changed the
	 * database contents, but let's do it anyway to be safe.)
	 */
	PushCopiedSnapshot(GetActiveSnapshot());
	UpdateActiveSnapshotCommandId();

	/* Create a QueryDesc, redirecting output to our tuple receiver */
	queryDesc = CreateQueryDesc(plan, queryString,
								GetActiveSnapshot(), InvalidSnapshot,
								dest, NULL, NULL, 0);

	/* call ExecutorStart to prepare the plan for execution */
	ExecutorStart(queryDesc, 0);

	/* run the plan */
	ExecutorRun(queryDesc, ForwardScanDirection, 0);

static void
refresh_by_heap_swap(Oid matviewOid, Oid OIDNewHeap, char relpersistence)
{
	finish_heap_swap(matviewOid, OIDNewHeap, false, false, true, true,
					 true,		/* reindex */
					 RecentXmin, ReadNextMultiXactId(), relpersistence);

case T_CreateTableAsStmt:
	address = ExecCreateTableAs(pstate, (CreateTableAsStmt *) parsetree,
								params, queryEnv, qc);
	break;

case T_RefreshMatViewStmt:

	/*
	 * REFRESH CONCURRENTLY executes some DDL commands internally.
	 * Inhibit DDL command collection here to avoid those commands
	 * from showing up in the deparsed command queue.  The refresh
	 * command itself is queued, which is enough.
	 */
	EventTriggerInhibitCommandCollection();
	PG_TRY(2);
	{
		address = ExecRefreshMatView((RefreshMatViewStmt *) parsetree,
									 queryString, qc);
	}
	PG_FINALLY(2);

/*
 * For materialized views, always skip data during table creation, and use
 * REFRESH instead (see below).
 */
if (is_matview)
{
	do_refresh = !into->skipData;
	into->skipData = true;
}

if (into->skipData)
{
	/*
	 * If WITH NO DATA was specified, do not go through the rewriter,
	 * planner and executor.  Just define the relation using a code path
	 * similar to CREATE VIEW.  This avoids dump/restore problems stemming
	 * from running the planner before all dependencies are set up.
	 */
	address = create_ctas_nodata(query->targetList, into);

	/*
	 * For materialized views, reuse the REFRESH logic, which locks down
	 * security-restricted operations and restricts the search_path.  This
	 * reduces the chance that a subsequent refresh will fail.
	 */
	if (do_refresh)
		RefreshMatViewByOid(address.objectId, true, false, false,
							pstate->p_sourcetext, qc);

ObjectAddress
ExecRefreshMatView(RefreshMatViewStmt *stmt, const char *queryString,
				   QueryCompletion *qc)
{
	Oid			matviewOid;
	LOCKMODE	lockmode;

	/* Determine strength of lock needed. */
	lockmode = stmt->concurrent ? ExclusiveLock : AccessExclusiveLock;

	/*
	 * Get a lock until end of transaction.
	 */
	matviewOid = RangeVarGetRelidExtended(stmt->relation,
										  lockmode, 0,
										  RangeVarCallbackMaintainsTable,
										  NULL);

	return RefreshMatViewByOid(matviewOid, false, stmt->skipData,
							   stmt->concurrent, queryString, qc);

