public Optional<Node> findByRange(Range range) {
    if (isPhantom()) {
        return Optional.empty();
    }
    if (!hasRange()) {
        return Optional.empty();
    }
    if (!getRange().get().contains(range)) {
        return Optional.empty();
    }
    for (Node child : getChildNodes()) {
        Optional<Node> found = child.findByRange(range);
        if (found.isPresent()) {
            return found;
        }
    }
    return Optional.of(this);

