@Override
public Map<Rule, Boolean> check(Rules rules, Facts facts) {
    Objects.requireNonNull(rules, "Rules must not be null");
    Objects.requireNonNull(facts, "Facts must not be null");
    triggerListenersBeforeRules(rules, facts);
    Map<Rule, Boolean> result = doCheck(rules, facts);
    triggerListenersAfterRules(rules, facts);
    return result;
}

private Map<Rule, Boolean> doCheck(Rules rules, Facts facts) {
    LOGGER.debug("Checking rules");
    Map<Rule, Boolean> result = new HashMap<>();
    for (Rule rule : rules) {
        if (shouldBeEvaluated(rule, facts)) {
            result.put(rule, rule.evaluate(facts));
        }
    }
    return result;

public InvoiceWithMetadata generateInvoice(final ImmutableAccountData account,
                                           @Nullable final BillingEventSet events,
                                           final AccountInvoices existingInvoices,
                                           @Nullable final UUID targetInvoiceId,
                                           final LocalDate targetDate,
                                           final Currency targetCurrency,
                                           @Nullable final DryRunInfo dryRunInfo,
                                           final Iterable<PluginProperty> inputProperties,
                                           final InternalCallContext context) throws InvoiceApiException {
    if (events == null) {
        return new InvoiceWithMetadata(null, Collections.emptySet(), Collections.emptyMap(), false, context);
    }

    validateTargetDate(targetDate, context);
    final LocalDate adjustedTargetDate = adjustTargetDate(existingInvoices.getInvoices(), targetDate);

    final LocalDate invoiceDate = context.toLocalDate(context.getCreatedDate());
    final InvoiceStatus invoiceStatus = events.isAccountAutoInvoiceDraft() ? InvoiceStatus.DRAFT : InvoiceStatus.COMMITTED;
    final DefaultInvoice invoice = targetInvoiceId != null ?
                                   new DefaultInvoice(targetInvoiceId, account.getId(), null, invoiceDate, adjustedTargetDate, targetCurrency, false, invoiceStatus) :
                                   new DefaultInvoice(account.getId(), invoiceDate, adjustedTargetDate, targetCurrency, invoiceStatus);

private void validateTargetDate(final LocalDate targetDate, final InternalTenantContext context) throws InvoiceApiException {
    final int maximumNumberOfMonths = config.getNumberOfMonthsInFuture(context);

    if (Months.monthsBetween(clock.getUTCToday(), targetDate).getMonths() > maximumNumberOfMonths) {
        throw new InvoiceApiException(ErrorCode.INVOICE_TARGET_DATE_TOO_FAR_IN_THE_FUTURE, targetDate.toString());
    }

private InvoiceWithMetadata generateKillBillInvoice(final ImmutableAccountData account, final LocalDate targetDate, final BillingEventSet billingEvents, final AccountInvoices accountInvoices, @Nullable final DryRunInfo dryRunInfo, final Iterable<PluginProperty> inputProperties, final InternalCallContext context) throws InvoiceApiException {
    final UUID targetInvoiceId;

    final boolean reuseDraftIfExist = isPropertyReuseDraftSet(inputProperties);
    final UUID reuseInvoiceDraftId = getReuseDraftInvoiceId(inputProperties);

    // Filter out DRAFT invoices for computation  of existing items unless Account is in AUTO_INVOICING_REUSE_DRAFT
    if (billingEvents.isAccountAutoInvoiceReuseDraft() || reuseDraftIfExist || reuseInvoiceDraftId != null) {
        final Invoice existingDraft = accountInvoices.getInvoices().stream()
                .filter(input -> input.getStatus() == InvoiceStatus.DRAFT && (reuseInvoiceDraftId == null || reuseInvoiceDraftId.equals(input.getId())))
                .findFirst()
                .orElse(null);
        targetInvoiceId = existingDraft != null ? existingDraft.getId() : null;
    } else {
        targetInvoiceId = null;
    }

    return generator.generateInvoice(account, billingEvents, accountInvoices, targetInvoiceId, targetDate, account.getCurrency(), dryRunInfo, inputProperties, context);

@Override
public void run() {
    boolean stop = exchange.isRouteStop();
    int num = index;
    boolean more = num < size;
    boolean first = num == 0;

    if (!stop && more && (first || continueProcessing(exchange, "so breaking out of pipeline", LOG))) {

        // prepare for next run
        ExchangeHelper.prepareOutToIn(exchange);

        // get the next processor
        AsyncProcessor processor = processors.get(index++);

        processor.process(exchange, this);
    } else {
        // copyResults is needed in case MEP is OUT and the message is not an OUT message
        ExchangeHelper.copyResults(exchange, exchange);

        // logging nextExchange as it contains the exchange that might have altered the payload and since
        // we are logging the completion it will be confusing if we log the original instead
        // we could also consider logging the original and the nextExchange then we have *before* and *after* snapshots
        if (LOG.isTraceEnabled()) {
            LOG.trace("Processing complete for exchangeId: {} >>> {}", exchange.getExchangeId(), exchange);
        }

        AsyncCallback cb = callback;
        taskFactory.release(this);
        reactiveExecutor.schedule(cb);

